import{z as i,x as l,o as e,c as n,q as r,j as B,D as a,d as s,s as o,S as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"可观测性收束","description":"","frontmatter":{"title":"可观测性收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-map.md","filePath":"cs/obs-map.md","lastUpdated":1791063341000}'),p={name:"cs/obs-map.md"};function d(m,E,c,f,_,h){const A=l("Mermaid");return e(),n("div",null,[E[2]||(E[2]=r('<h1 id="可观测性收束" tabindex="-1">可观测性收束 <a class="header-anchor" href="#可观测性收束" aria-label="Permalink to &quot;可观测性收束&quot;">​</a></h1><div class="epigraph"><p>观测不是为了看清系统，是为了让关于系统的争论变成可以测量的命题；测不准的地方，剩下的只有资历与嗓门。</p><footer>—— 据 Gregg, <em>Systems Performance</em>, 2nd ed., 2018 与 <em>BPF Performance Tools</em>, 2019；Google SRE 书整理</footer></div><p><a href="/cs/obs-postmortem-culture">上一课</a>把事故变成组织资产：改进项带着负责人与期限落进系统。本课程到此收束。九课走过的路可以钉成一条闭环：第一课立下三笔工程账——基数、成本、采样——给所有信号定了预算纪律；工具组四课补足应用代码之外的眼睛，eBPF 动态埋点、perf 的测量学、火焰图的展示、内存调试的正确性；工程组四课把单机证据升到组织行为，分布式追踪管一次请求、SLO 管全体流量、事故指挥管当下、复盘管以后。本课不引入新机制，只验一遍闭环闭合，并把全课程的边界收清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>零散学过九课之后，缺口是「它们为什么是这个顺序」。答案是一条证据链：改进项要落地，必须知道同类事故会不会再发生，这需要 SLO 的预算账本；账本要准，SLI 的分母不能错，这需要指标基数与直方图纪律；定位到具体请求要追踪的传播合同；定位到单机函数要 perf 与火焰图的测量学与展示；连「错误」本身的捕获都要内存调试的检测器。抽掉任何一环，环上别处都会退化：没有预算纪律的追踪是存储黑洞，没有复盘的指挥是重复事故，没有测量学的火焰图是随机形状。闭环的检验标准只有一条：下一次同类事故，损失更小、发现更早、恢复更快。</p><p><span class="marginnote">术语翻译：SLI 是「实际测到的成绩单」，比如 99.2% 的请求在 300 毫秒内返回；SLO 是「给自己定的及格线」，比如 99%。错误预算就是允许不及格的份额——1% 的请求可以慢或失败，花完就得停下来修质量。</span></p>',6)),(e(),B(t,null,{default:a(()=>[o(A,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20INST%5B%22%E5%9F%8B%E7%82%B9%E4%B8%8E%E9%A2%84%E7%AE%97%E7%BA%AA%E5%BE%8B%22%5D%20--%3E%20DET%5B%22SLO%20%E7%83%A7%E9%80%9F%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20RESP%5B%22%E4%BA%8B%E6%95%85%E6%8C%87%E6%8C%A5%E6%AD%A2%E6%8D%9F%22%5D%0A%20%20RESP%20--%3E%20LEARN%5B%22%E6%97%A0%E6%8C%87%E8%B4%A3%E5%A4%8D%E7%9B%98%22%5D%0A%20%20LEARN%20--%3E%20ACT%5B%22%E6%94%B9%E8%BF%9B%E9%A1%B9%E8%90%BD%E5%9C%B0%22%5D%0A%20%20ACT%20--%3E%20HARDEN%5B%22%E9%98%B2%E5%BE%A1%E4%B8%8E%E8%A7%82%E6%B5%8B%E5%8A%A0%E5%9B%BA%22%5D%0A%20%20HARDEN%20--%3E%20INST%0A%20%20TOOLS%5B%22%E5%B7%A5%E5%85%B7%E7%BB%84%EF%BC%9AeBPF%E3%80%81perf%E3%80%81%E7%81%AB%E7%84%B0%E5%9B%BE%E3%80%81%E5%86%85%E5%AD%98%E8%B0%83%E8%AF%95%22%5D%20--%3E%20INST%0A%20%20TOOLS%20--%3E%20RESP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r('<p><span class="marginnote">这条闭环与<a href="/cs/chaos-engineering">混沌工程</a>相接：混沌是把同一个回路反向跑一遍——主动注入故障，用同一套 SLO 测量面检验防御，赶在事故之前让闭环转一圈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收束成三句口诀。其一，预算先行：指标吃基数预算，追踪吃存储预算，系统吃错误预算——可观测性的一切设计都是稀缺资源上的分配，先登记后消费。其二，证据分层：单机与跨机、单请求与全流量、慢与坏，各自的工具链不同，不要用一张图回答所有问题——火焰图不回答因果，追踪不回答聚合，SLO 不回答单次诊断。其三，回路闭合：检测、止损、复盘、加固，任何一环不落地，观测系统就退化为报表工厂。落地与否的判据是机器可查的：闸门在流水线里、改进项有期限、防御进了测试。</p><p><span class="marginnote">直觉类比：三支柱像一次体检——指标是体温血压那几行数字，便宜、好比对，但不会讲故事；日志是病历本，每件事都记但翻起来费劲；追踪是这次就诊的完整流程单，挂号、检查、取药每步耗时一目了然。</span></p>',4)),(e(),B(t,null,{default:a(()=>[o(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E4%B8%AA%E8%A7%82%E6%B5%8B%E9%97%AE%E9%A2%98%22%5D%20--%3E%20A%7B%22%E9%97%AE%E7%9A%84%E6%98%AF%E5%93%AA%E4%B8%80%E7%B1%BB%22%7D%0A%20%20A%20--%3E%7C%22%E6%95%B4%E4%BD%93%E5%A4%9F%E4%B8%8D%E5%A4%9F%E5%A5%BD%22%7C%20SLO%5B%22SLO%20%E9%A2%84%E7%AE%97%E4%B8%8E%E7%83%A7%E9%80%9F%22%5D%0A%20%20A%20--%3E%7C%22%E8%BF%99%E4%B8%80%E6%AC%A1%E8%AF%B7%E6%B1%82%E5%8F%91%E7%94%9F%E4%BA%86%E4%BB%80%E4%B9%88%22%7C%20TR%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E8%BF%BD%E8%B8%AA%22%5D%0A%20%20A%20--%3E%7C%22%E5%8D%95%E6%9C%BA%E5%93%AA%E9%87%8C%E6%85%A2%22%7C%20PF%5B%22perf%20%E5%8A%A0%E7%81%AB%E7%84%B0%E5%9B%BE%22%5D%0A%20%20A%20--%3E%7C%22%E5%93%AA%E9%87%8C%E5%9D%8F%E4%BA%86%22%7C%20MEM%5B%22%E5%86%85%E5%AD%98%E8%B0%83%E8%AF%95%E6%A3%80%E6%B5%8B%E5%99%A8%22%5D%0A%20%20A%20--%3E%7C%22%E7%8E%B0%E6%88%90%E6%8E%A5%E5%8F%A3%E6%B2%A1%E6%9C%89%22%7C%20BP%5B%22eBPF%20%E5%8A%A8%E6%80%81%E5%9F%8B%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>深钻层与主干的关系也在此说清。主干课钉机制：<a href="/cs/observability-pillars">可观测三支柱</a>钉信号分工，<a href="/cs/distributed-tracing">分布式追踪</a>钉树与采样，<a href="/cs/ebpf-observability">eBPF 观测</a>钉核内聚合，<a href="/cs/perf-sampling">perf 采样</a>钉采样路径；本课程钉的是把机制变成生产纪律的工程决策——工具怎么选、预算怎么分、组织怎么动。两层合起来才是完整的可观测性：只有机制，工具是 demo；只有纪律，决策没有根据。闭环为什么成立：复盘改进的防御改变故障分布，分布变化由 SLO 账本度量，度量反过来指明下一处观测投入——这是一个能自我校准的反馈系统，而不是一份静态清单。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>全课程的边界一次收清。可观测性不是性能优化：它提供证据，优化是拿着证据做决策的另一门手艺。它不是安全审计：合规原文与证据链是 <a href="/cs/siem-logging">SIEM</a> 与<a href="/cs/incident-response">事件响应</a>的口径，观测平面假设操作者是合法的。它不是测试：混沌工程从主动侧检验同一套 SLO 面，缺陷要在开发阶段抓的归测试。它也有自己的失效模式：观测系统自身故障时你最需要它——独立通道与合成探测是硬要求；观测数据成为考核指标时，数据会开始说谎。本课程到此收束：从显式网络上的三笔账，到证据链闭成的回路，测得准的系统才谈得上管得好。</p><p><span class="marginnote">常见误区：初学者以为观测系统装好就一劳永逸。观测系统自己也会故障、也占预算，而你最需要它的时刻往往正是它挂掉的时刻——这就是独立通道与合成探测（定时模拟用户访问）是硬要求的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>九课是一条闭环：埋点、检测、止损、复盘、加固，回到埋点。</li><li>预算先行、证据分层、回路闭合，三句口诀各管一类错误。</li><li>主干钉机制，深钻钉工程纪律，两层缺一不可。</li><li>可观测性不是优化、不是审计、不是测试；边界即分工。</li><li>观测平面自身会故障也会说谎，要独立通道、要防指标考核化。</li><li>出处：Gregg, <em>Systems Performance</em> 与 <em>BPF Performance Tools</em>；Google SRE 书；主干课三支柱、追踪、eBPF、perf 的口径。</li></ul>',7))])}const T=i(p,[["render",d]]);export{D as __pageData,T as default};
